  bash rex24.sh --logs                  查看服务日志
  bash rex24.sh --network               仅BBR/FQ、3F2网络参数与恢复
  bash rex24.sh --micro-menu            28项控制中心
  bash rex24.sh --micro-28              --apply-defaults 的兼容别名
  bash rex24.sh --cleanup-menu          设置每日磁盘清理
  bash rex24.sh --cleanup-preview       预览清理范围
  bash rex24.sh --cleanup               立即清理
  bash rex24.sh --host-status           查看主机实际运行值
  bash rex24.sh --host-recover          恢复未完成的主机/网卡事务
  bash rex24.sh --xray-info [配置路径]    只查看 target/dest、serverNames
